<template>
  <v-app>
    <v-main>
      <v-container>
        <h1>File Management</h1>

        <!-- Upload Section -->
        <v-row class="upload-section">
          <v-col cols="12" sm="8">
            <v-file-input
              v-model="fileInput"
              label="Select a file"
              show-size
              prepend-icon="mdi-paperclip"
            />
          </v-col>
          <v-col cols="12" sm="4">
            <v-btn
              color="primary"
              :disabled="!fileInput"
              @click="uploadFile"
            >
              Upload File
            </v-btn>
          </v-col>
        </v-row>

        <!-- Message Display -->
        <v-alert
          v-if="message.text"
          :type="message.isError ? 'error' : 'success'"
          class="message"
          dismissible
          @input="message.text = ''"
        >
          {{ message.text }}
        </v-alert>

        <!-- File List Table -->
        <h2>Files</h2>
        <v-data-table
          :headers="headers"
          :items="files"
          :items-per-page="10"
          :loading="loading"
          class="elevation-1"
        >
          <template #item.thumbnail="{ item }">
            <v-img
              v-if="isImage(item.name)"
              :src="`${apiUrl}/uploads/${item.name}`"
              max-width="60"
              max-height="60"
              class="cursor-pointer"
              @click="enlargeImage(`${apiUrl}/uploads/${item.name}`)"
            />
          </template>

          <template #item.name="{ item }">
            <a :href="`${apiUrl}/uploads/${item.name}`" target="_blank">
              {{ item.name }}
            </a>
          </template>

          <template #item.size="{ item }">
            {{ formatFileSize(item.size) }}
          </template>

          <template #item.modified="{ item }">
            {{ formatDate(item.modified) }}
          </template>

          <template #item.actions="{ item }">
            <v-btn color="error" small @click="deleteFile(item.name)">
              Delete
            </v-btn>
          </template>
        </v-data-table>

        <!-- Dialog to Show Enlarged Image -->
        <v-dialog v-model="dialog" max-width="600px">
          <v-card>
            <v-img :src="enlargedImage" aspect-ratio="1.5" contain />
            <v-card-actions>
              <v-spacer></v-spacer>
              <v-btn text @click="dialog = false">Close</v-btn>
            </v-card-actions>
          </v-card>
        </v-dialog>
      </v-container>
    </v-main>
  </v-app>
</template>

<script setup>
import { ref, onMounted } from 'vue';

// Constants
const apiUrl = 'http://192.168.50.126:3000';

// Reactive state
const fileInput = ref(null);
const files = ref([]);
const loading = ref(false);
const message = ref({ text: '', isError: false });
const dialog = ref(false);
const enlargedImage = ref('');

// Table headers
const headers = [
  { title: 'Thumbnail', key: 'thumbnail', sortable: false },
  { title: 'Name', key: 'name', sortable: true },
  { title: 'Size', key: 'size', sortable: true },
  { title: 'Modified', key: 'modified', sortable: true },
  { title: 'Actions', key: 'actions', sortable: false },
];

// Utility functions
const formatFileSize = (bytes) => {
  if (bytes === 0) return '0 B';
  const units = ['B', 'KB', 'MB', 'GB'];
  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  return `${(bytes / Math.pow(1024, i)).toFixed(2)} ${units[i]}`;
};

const formatDate = (date) => {
  return new Date(date).toLocaleString('en-US', {
    year: 'numeric',
    month: 'short',
    day: 'numeric',
    hour: '2-digit',
    minute: '2-digit',
  });
};

const showMessage = (text, isError = false) => {
  message.value = { text, isError };
  setTimeout(() => {
    message.value.text = '';
  }, 3000);
};

// File type check
const isImage = (filename) => {
  return /\.(jpe?g|png|gif|bmp|webp)$/i.test(filename);
};

const enlargeImage = (url) => {
  enlargedImage.value = url;
  dialog.value = true;
};

// API interactions
const fetchFiles = async () => {
  loading.value = true;
  try {
    const response = await fetch(`${apiUrl}/files`);
    if (!response.ok) throw new Error('Failed to fetch files');
    const data = await response.json();
    files.value = data.files.length ? data.files : [];
    if (!data.files.length) {
      showMessage('No files available');
    }
  } catch (error) {
    showMessage(`Error fetching files: ${error.message}`, true);
  } finally {
    loading.value = false;
  }
};

const uploadFile = async () => {
  if (!fileInput.value) {
    showMessage('Please select a file', true);
    return;
  }

  const formData = new FormData();
  formData.append('file', fileInput.value);

  try {
    const response = await fetch(`${apiUrl}/upload`, {
      method: 'POST',
      body: formData,
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || 'Upload failed');
    showMessage(data.message);
    fileInput.value = null;
    await fetchFiles();
  } catch (error) {
    showMessage(`Error uploading file: ${error.message}`, true);
  }
};

const deleteFile = async (filename) => {
  if (!confirm(`Are you sure you want to delete ${filename}?`)) return;

  try {
    const response = await fetch(`${apiUrl}/files/${filename}`, {
      method: 'DELETE',
    });
    const data = await response.json();
    if (!response.ok) throw new Error(data.error || 'Deletion failed');
    showMessage(data.message);
    await fetchFiles();
  } catch (error) {
    showMessage(`Error deleting file: ${error.message}`, true);
  }
};

// Initialize
onMounted(fetchFiles);
</script>

<style scoped>
.upload-section {
  margin: 20px 0;
}
.message {
  margin: 10px 0;
}
h1,
h2 {
  margin-bottom: 20px;
}
.cursor-pointer {
  cursor: pointer;
}
</style>
